  <script>
    // Mobile Menu
    function toggleMobileMenu() {
      document.getElementById('mobileMenu').classList.toggle('active');
      document.body.style.overflow = document.getElementById('mobileMenu').classList.contains('active') ? 'hidden' : '';
    }

    // Donate Modal
    let selectedDonationAmount = 100;

    function openDonateModal() {
      document.getElementById('donateModal').classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeDonateModal() {
      document.getElementById('donateModal').classList.remove('active');
      document.body.style.overflow = '';
    }

    function selectAmount(amount) {
      selectedDonationAmount = amount;
      document.querySelectorAll('.donate-amount').forEach(btn => {
        btn.classList.toggle('selected', parseInt(btn.dataset.amount) === amount);
      });
      document.getElementById('customAmount').value = '';
      updateImpact(amount);
    }

    function updateCustomAmount() {
      const custom = document.getElementById('customAmount').value;
      if (custom) {
        selectedDonationAmount = parseInt(custom);
        document.querySelectorAll('.donate-amount').forEach(btn => btn.classList.remove('selected'));
        updateImpact(custom);
      }
    }

    function updateImpact(amount) {
      const impacts = {
        25: 'emergency blankets',
        50: 'a family with food and water for one week',
        100: 'emergency shelter materials for a household',
        250: 'disaster response training for a volunteer',
        500: 'emergency medical supplies',
        1000: 'a family with comprehensive relief supplies'
      };
      const impact = impacts[amount] || ' lifesaving supplies';
      document.getElementById('donateImpact').innerHTML = `<p>Your <strong>$${amount}</strong> donation will provide ${impact}.</p>`;
    }

    function submitDonation() {
      alert(`Thank you for your generous donation of $${selectedDonationAmount}! This is a demo — in production, this would redirect to a secure payment form.`);
      closeDonateModal();
    }

    // Close modal on overlay click
    document.getElementById('donateModal').addEventListener('click', function(e) {
      if (e.target === this) closeDonateModal();
    });

    // Accordion
    function toggleAccordion(header) {
      const item = header.parentElement;
      const wasActive = item.classList.contains('active');

      document.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));

      if (!wasActive) {
        item.classList.add('active');
      }
    }

    // News Carousel
    let carouselPosition = 0;
    const track = document.getElementById('carouselTrack');

    function moveCarousel(direction) {
      const cards = track.children.length;
      const cardWidth = track.children[0].offsetWidth + 24;
      const visibleCards = Math.floor(track.parentElement.offsetWidth / cardWidth);
      const maxPosition = cards - visibleCards;

      carouselPosition = Math.max(0, Math.min(maxPosition, carouselPosition + direction));
      track.style.transform = `translateX(-${carouselPosition * cardWidth}px)`;
    }

    // Animated Counters
    function animateCounters() {
      const stats = document.querySelectorAll('.stat-number');

      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const el = entry.target;
            const target = parseInt(el.dataset.target);
            const prefix = el.dataset.prefix || '';
            const suffix = el.dataset.suffix || '';
            const duration = 2000;
            const start = performance.now();

            function update(currentTime) {
              const elapsed = currentTime - start;
              const progress = Math.min(elapsed / duration, 1);
              const eased = 1 - Math.pow(1 - progress, 3);
              const current = Math.floor(eased * target);

              if (target >= 1000000) {
                el.textContent = prefix + (current / 1000000).toFixed(1) + 'M' + suffix;
              } else if (target >= 1000) {
                el.textContent = prefix + (current / 1000000).toFixed(1) + 'M' + suffix;
              } else {
                el.textContent = prefix + current.toLocaleString() + suffix;
              }

              if (progress < 1) {
                requestAnimationFrame(update);
              }
            }

            requestAnimationFrame(update);
            observer.unobserve(el);
          }
        });
      }, { threshold: 0.5 });

      stats.forEach(stat => observer.observe(stat));
    }

    // Initialize
    document.addEventListener('DOMContentLoaded', () => {
      animateCounters();
    });

    // Escape key closes modals
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeDonateModal();
        if (document.getElementById('mobileMenu').classList.contains('active')) {
          toggleMobileMenu();
        }
      }
    });
  </script>
